import ledger
S = "ledgers/CF8/scripts/CF8-c-r4"
mut_lines = [l for l in open(f"{S}/mutate_graders_CF8_r4.out", encoding="utf-8") if l.startswith("KILLED ")]
mutants = []
for l in mut_lines:
    m = re.match(r"KILLED (\S+?): (.*) -> (\S+) \(seed (\d+)\)", l.strip())
    name, desc, killed, seed = m.group(1), m.group(2), m.group(3), m.group(4)
    mutants.append({"name": name[:-3], "description": desc, "killed_by": f"{killed} (seed {seed})"})
# the 47 existing mutants (round-3 and earlier) are in the 50-mutant run of mutate_graders_CF8.out
existing = [l for l in open(f"{S}/mutate_graders_CF8.out", encoding="utf-8") if l.startswith("KILLED ")]
names_new = {m["name"] for m in mutants}
for l in existing:
    m = re.match(r"KILLED (\S+?): (.*) -> (\S+) \(seed (\d+)\)", l.strip())
    if m.group(1)[:-3] not in names_new:
        mutants.append({"name": m.group(1)[:-3], "description": m.group(2), "killed_by": f"{m.group(3)} (seed {m.group(4)})"})
